// ===========================================================================
// Фикстура «ощущение удара»: hit-stop, экранная вспышка, хит-эффекты.
//
// Сцена намеренно бедная, чтобы тест мерил только отклик:
//   * <player> высоко в воздухе — падает, его и останавливает hit-stop;
//   * <wall> земля — есть на что упасть;
//   * <enemy> на земле — цель для выстрела (событие hit);
//   * подписка $.hits.on('#foe', 'crit') — одна строка без ручного кода.
//
// Результаты тест читает через $.eval: позиции, $.time.frame(), $.time.frozen(),
// $.hits.stats(), $.fx.flashLeft(), $.camera._state.shake_amp.
// ===========================================================================

$.ready(() => {
    $.world.gravity(0, 900).color('#101820').bounds(-200, -200, 1600, 1200);

    // Земля: игрок падает на неё, враг стоит.
    $('<wall>', { id: 'ground' }).at(400, 560).size(1200, 40).appendTo($.world);

    // Игрок высоко: 30 кадров разгона — и он ещё в воздухе.
    $('<player>', { id: 'hero' }).at(200, 100).size(26, 30).appendTo($.world);

    // Враг на земле — цель для выстрела. Он динамический, поэтому событие
    // hit от Box2D включено само (см. contacts_enabled в core.js).
    $('<enemy>', { id: 'foe' }).at(600, 500).size(28, 40).appendTo($.world);

    // Одна строка: полный хит-фидбек по событию 'hit' на враге.
    $.hits.on('#foe', 'crit');

    // Счётчик попаданий — по нему тест понимает, что событие дошло.
    $.store.set('feelHits', 0);
    $('#foe').on('hit', () => $.store.set('feelHits', $.store.get('feelHits') + 1));
});
